package com.restaurantmanagement.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { record Error(boolean success,String message,String errorCode,Instant timestamp){} @ExceptionHandler(NotFoundException.class) ResponseEntity<Error> missing(NotFoundException e){return ResponseEntity.status(404).body(new Error(false,e.getMessage(),"NOT_FOUND",Instant.now()));} @ExceptionHandler(Exception.class) ResponseEntity<Error> error(Exception e){return ResponseEntity.status(500).body(new Error(false,"Request could not be processed","INTERNAL_ERROR",Instant.now()));} }
